#!/usr/bin/env python3
"""Replay one CrossCheck telemetry request.

Reads a single UTF-8 JSON document from stdin until EOF, writes exactly one
JSON document to stdout and exits zero.  Nothing is written to stdout other
than the answer; no files, processes, threads or sockets are used.
"""

import os
import sys

from crosscheck.strictjson import INVALID, loads
from crosscheck.crosscheck import CrossCheck

_DEBUG = bool(os.environ.get("CROSSCHECK_DEBUG"))


def run(document):
    streams = document["streams"]
    answers = []
    for stream in streams:
        engine = CrossCheck(stream["topology"])
        answers.append({"events": engine.replay(stream["events"],
                                                stream["settings"])})
    return {"streams": answers}


def main():
    data = sys.stdin.buffer.read()
    try:
        request = loads(data)
    except Exception:
        sys.stdout.write(INVALID)
        return 0
    try:
        import json
        answer = json.dumps(run(request), separators=(",", ":"),
                            allow_nan=False)
    except BaseException:
        if _DEBUG:
            raise
        return_code = 1
    else:
        sys.stdout.write(answer)
        return_code = 0
    return return_code


if __name__ == "__main__":
    sys.exit(main())
