        fixed = {}
        order = []
        conf = {}
        remaining = list(self.flows)
        while remaining:
            scores = {}
            for f in remaining:
                evidence = [(v, trials) for v in pools[f]]
                for r in f:
                    if r == -1:
                        continue
                    rems = []
                    for t in range(trials):
                        values = {}
                        for g in self.incident[r]:
                            pool = pools[g]
