    def validate(self, event):
        payload = self.snaps[event["id"]]
        loads = self.predicted()
        cut = self.settings["cutoff"]
        bias = self.settings["bias"]
        tau = self.settings["tau"]
        checked = passed = 0
        failed = []
        for index, pair in enumerate(self.flows):
            expected = loads[pair]
            if expected is None:
                continue
            record = payload["links"][index]
            cn, cd = record[3], record[4]
            if cn * cut[1] < cut[0] * cd:
                continue
            x = record[2] * 1000000
            y = expected * (1000000 - bias)
            ok = 1000000 * abs(x - y) <= tau * max(x, y)
            for k in self.keys[pair]:
                checked += 1
                if ok:
                    passed += 1
                else:
                    failed.append(k)
        if checked == 0:
            consistent = None
        else:
            gam = self.settings["gamma"]
            consistent = passed * gam[1] >= checked * gam[0]
        return {"checked": checked, "passed": passed,
                "consistent": consistent, "failed": sorted(failed)}

    def replay(self, events, settings):
        self.reset(settings)
        out = []
        for event in events:
            op = event["op"]
