#!/usr/bin/env python3
"""Exhaustive check of the two-pointer band against literal enumeration."""
import random
import sys

sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/tmp')

from crosscheck.common_utils import select_band          # noqa: E402
from reference import Ref                                # noqa: E402


def brute(items, epsilon):
    """Literal enumeration over all endpoint pairs of observed values."""
    return Ref.band(items, epsilon)


def main(rounds=4000):
    rng = random.Random(12345)
    bad = 0
    values_pool = [0, 1, 2, 3, 5, 7, 9, 10, 11, 12, 25, 99, 100, 101, 999, 1000,
                   1000000, 10 ** 9]
    for case in range(rounds):
        size = rng.randint(1, 8)
        entries = [(rng.choice(values_pool), rng.randint(1, 40)) for _ in range(size)]
        counts = {}
        for v, w in entries:
            counts[v] = counts.get(v, 0) + w
        epsilon = rng.choice([0, 1, 100000, 111111, 250000, 99999, 125000,
                              rng.randint(0, 250000), 249999, 250000])
        got = select_band(counts, epsilon)
        want = brute(entries, epsilon)
        if got != want:
            bad += 1
            print("BAND MISMATCH", sorted(counts.items()), epsilon, got, want)
            if bad > 5:
                return 1
    # boundary-focused sweep: epsilon exactly at the inclusive threshold
    for lo in range(0, 40):
        for hi in range(lo, lo + 40):
            for bump in (-1, 0, 1):
                if hi == 0:
                    continue
                eps = 1000000 * (hi - lo) // hi + bump
                if not 0 <= eps <= 250000:
                    continue
                for weight_lo in (1, 3):
                    for weight_hi in (1, 2):
                        counts = {}
                        if lo == hi:
                            counts[lo] = weight_lo + weight_hi
                        else:
                            counts[lo] = weight_lo
                            counts[hi] = weight_hi
                        entries = [(v, w) for v, w in counts.items()]
                        got = select_band(counts, eps)
                        want = brute(entries, eps)
                        if got != want:
                            bad += 1
                            print("BOUNDARY MISMATCH", counts, eps, got, want)
    print("band checks done, mismatches:", bad)
    return 1 if bad else 0


sys.exit(main())
