#!/usr/bin/env python3
"""Structural invariants over random replays, checked on the JSON boundary."""
import json
import math
import random
import subprocess
import sys
from fractions import Fraction
from math import gcd

sys.path.insert(0, '/workspace/tmp')
import diff_test  # noqa: E402

MAIN = '/workspace/submission/main.py'
problems = []


def walk_numbers(node, path=""):
    if isinstance(node, bool):
        return  # booleans are only legal in the documented spots, checked below
    if isinstance(node, float):
        problems.append("float in output at " + path)
    if isinstance(node, list):
        for i, child in enumerate(node):
            walk_numbers(child, path + "[%d]" % i)


def check_case(index, request, answer):
